func calculateASCIISum(input string) int {
	sum := 0
	length := len(input)

	for _, char := range input {
		if (char >= 'A' && char <= 'Z') || (char >= 'a' && char <= 'z') {
			sum += int(char)
		} else {
			if char >= '!' && char <= '%' {
				sum += int(char) * int(char)
			} else {
				sum += int(char) * length
			}
		}
	}

	return sum
}

func main() {
