func convertKelvinToCelsius(kelvin float64) float64 {
	const absoluteZeroKelvin = -273.15
	const maxFloat64 = 1.7976931348623157e+308

	if kelvin < absoluteZeroKelvin {
		return math.Inf(-1) // Return negative infinity for invalid temperatures
	}

	// Check if temperature exceeds the maximum representable value in floating-point format
	if kelvin > maxFloat64 {
		return math.Inf(1) // Return positive infinity for temperatures exceeding the maximum
	}

	celsius := kelvin + absoluteZeroKelvin

	// Round the result to two decimal places
	roundedCelsius := math.Round(celsius*100) / 100

	return roundedCelsius
}

func main() {
