				wordStart = -1
			}
		}
	}
	if wordStart != -1 {
		wc.AddWord(input[wordStart:])
	}
}

func countUniqueWordsHandler(w http.ResponseWriter, r *http.Request) {
	input := r.URL.Query().Get("input")
	if input == "" {
		http.Error(w, "Input parameter 'input' is required", http.StatusBadRequest)
		return
