	// Merge consecutive separators into a single separator
	input = strings.ReplaceAll(input, separator+separator, separator)

	// Split the string into parts using the separator
	parts := strings.Split(input, separator)

	// Validate each part and discard if it does not meet the requirement
	validParts := []string{}
	for _, part := range parts {
		if len(part) >= 3 {
