```go
import (
    "errors"
    "strings"
)

func splitString(str, sep string) ([]string, error) {
    parts := strings.Split(str, sep)
    result := []string{}

    for i := 0; i < len(parts); i++ {
        // Skip empty parts
        if len(parts[i]) == 0 {
            continue
        }

        // Merge consecutive separators
        if i > 0 && len(result) > 0 && len(parts[i-1]) == 0 {
            result[len(result)-1] += sep
        }

        // Add valid parts
        if len(parts[i]) >= 3 {
            result = append(result, parts[i])
        }
    }

    if len(result) < 3 {
        return nil, errors.New("Insufficient parts")
    }

    return result[:3], nil
}
```

