}

// Function to check if a list is fit into non-decreasing or non-increasing order
func isMonotonic(list []int) bool {
	increasing := sort.IntsAreSorted(list)
	decreasing := sort.SliceIsSorted(list, func(i, j int) bool { return list[i] > list[j] })
	// If list is neither non-decreasing nor non-increasing, it's not monotonic
	if !increasing && !decreasing {
		return false
	}
	return true
}

// Function to perform deep check on the given list of lists
func monotonicDeep(list [][]int, strict bool) bool {
	for i, sublist := range list {
