	decreasing := sort.SliceIsSorted(list, func(i, j int) bool { return list[i][0] > list[j][0] })
	if !increasing && !decreasing {
		// If overall list is not non-decreasing nor non-increasing, it's not monotonic
		fmt.Println("Overall list is not monotonic")
