```go
func MustA() AType {
	a, err := A()
	if err != nil {
		panic(err)
	}
	return a
}

func MustB() BType {
	b, err := B()
	if err != nil {
		panic(err)
	}
	return b
}

func MustC() CType {
	c, err := C()
	if err != nil {
		panic(err)
	}
	return c
}
```

And then use it like:

```go
a := MustA()
b := MustB()
c := MustC()
```"}]

