```go
package main

import "fmt"

func tribonacciPrime(n int, k int) int {
    // Prepare Tribonacci sequence
    var trib = make([]int, n+1)
    trib[0] = 0
    trib[1] = 0
    trib[2] = 1
    for i := 3; i <= n; i++ {
        trib[i] = trib[i-3] + trib[i-2] + trib[i-1]
    }
    // Prepare prime number table
    var prime = make([]bool, n+1)
    for i := 2; i <= n; i++ {
        prime[i] = true
    }
    p := 2
    for p*p <= n {
        if prime[p] == true {
            for i := p * p; i <= n; i += p {
                prime[i] = false
            }
        }
        p += 1
    }

    // Calculate end result.
    for i := 2; i <= n; i++ {
        if prime[i] && i >= k {
            trib[i] -= trib[i-k]
        }
    }

    return trib[n]
}

func main() {
    fmt.Println(tribonacciPrime(10, 2))
}
```

