```go
func ProductExceptSelf(nums []int) []int {
    size := len(nums)
    output := make([]int, size)

    // initialize output with 1
    for i := 0; i < size; i++ {
        output[i] = 1
    }

    // multiply from left side (for each position, multiply everything that comes before)
    leftProduct := 1
    for i := 0; i < size; i++ {
        output[i] *= leftProduct
        leftProduct *= nums[i]
    }

    // multiply from right side (for each position, multiply everything that comes after)
    rightProduct := 1
    for i := size - 1; i >= 0; i-- {
        output[i] *= rightProduct
        rightProduct *= nums[i]
    }

