type Heap struct {
    List     []int
    CmpFunc  func(int, int) bool
}

func NewHeap(cmpFunc func(int, int) bool) *Heap {
    return &Heap{
        List: make([]int, 0),
        CmpFunc: cmpFunc,
    }
}

func (h *Heap) Push(value int) {
    h.List = append(h.List, value)
    h.HeapifyUp(len(h.List) - 1)
}

func (h *Heap) Pop() int {
    value := h.List[0]
    h.List[0] = h.List[len(h.List)-1]
    h.List = h.List[:len(h.List)-1]
    h.HeapifyDown(0)
    return value
}

func (h *Heap) HeapifyUp(index int) {
    for index > 0 {
        parent := (index - 1) / 2
        if h.CmpFunc(h.List[index], h.List[parent]) {
            h.List[parent], h.List[index] = h.List[index], h.List[parent]
            index = parent
        } else {
            break
        }
    }
}

func (h *Heap) HeapifyDown(index int) {
    for index < len(h.List) {
        left := index*2 + 1
        right := index*2 + 2
        smallest := index
        if left < len(h.List) && h.CmpFunc(h.List[smallest], h.List[left]) {
            smallest = left
        }
        if right < len(h.List) && h.CmpFunc(h.List[smallest], h.List[right]) {
            smallest = right
        }
        if smallest != index {
            h.List[smallest], h.List[index] = h.List[index], h.List[smallest]
            index = smallest
        } else {
            break
        }
    }
}

func Median(arr []int, cmpFunc func(int, int) bool) float64 {
    minHeap := NewHeap(cmpFunc)
    maxHeap := NewHeap(func(a, b int) bool {
        return !cmpFunc(a, b)
    })
