            maxHeap.Push(minHeap.Pop())
        } else if len(maxHeap.List) > len(minHeap.List)+1 {
            minHeap.Push(maxHeap.Pop())
        }
    }
    if len(arr)%2 == 0 {
        return float64(minHeap.List[0]+maxHeap.List[0]) / 2
    } else {
