    if len(list1) == 0 {
        return list1
    }

    midIndex := len(list1) / 2
    var midVal float64
    if len(list1)%2 == 0 {
        midVal = (float64(list1[midIndex]) + float64(list1[midIndex-1])) / 2.0
    } else {
        midVal = float64(list1[midIndex])
    }

    refList := []int{list1[0], int(midVal), list1[len(list1)-1]}
    sumRefVals := list1[0] + int(midVal) + list1[len(list1)-1]

    primeList := make([]int, 0)
    evenList := make([]int, 0)
    oddList := make([]int, 0)
    mixedList := make([]int, 0)

    var targetList []int

    if refList[0]%2 == 0 && refList[1]%2 == 0 && refList[2]%2 == 0 {
        targetList = evenList
    } else if refList[0]%2 != 0 && refList[1]%2 != 0 && refList[2]%2 != 0 {
        targetList = oddList
    } else if isPrime(refList[0]) && isPrime(refList[1]) && isPrime(refList[2]) {
        targetList = primeList
    } else {
        targetList = mixedList
    }

    targetList = append(targetList, list1...)

    if sumRefVals%5 == 0 {
        sort.Ints(targetList)
    } else if sumRefVals%3 == 0 && sumRefVals%5 != 0 {
        sort.Sort(sort.Reverse(sort.IntSlice(targetList)))
    } else {
        primes := make([]int, 0)
        nonPrimes := make([]int, 0)
        for _, num := range targetList {
            if isPrime(num) {
                primes = append(primes, num)
            } else {
                nonPrimes = append(nonPrimes, num)
            }
        }
        sort.Ints(primes)
        targetList = interleave(primes, nonPrimes)
    }

    result := append(primeList, append(evenList, append(oddList, mixedList...)...)...)

    return result
}

// Helper function to interleave 2 slice of integers.
func interleave(slice1, slice2 []int) (result []int) {
    for i := 0; i < len(slice1) || i < len(slice2); i++ {
        if i < len(slice1) {
            result = append(result, slice1[i])
        }
        if i < len(slice2) {
            result = append(result, slice2[i])
        }
    }
    return result
}
