func NextSmallestK(lst []int, k int) interface{} {
	if len(lst) == 0 || len(lst) < k {
		return nil
	}

	sort.Ints(lst)
	distinct := make([]int, 0)
	distinct = append(distinct, lst[0])

	for i := 1; i < len(lst); i++ {
		if lst[i] != lst[i-1] {
			distinct = append(distinct, lst[i])
		}
	}

	if len(distinct) < k {
