func digits(n int) int {
	nStr := strconv.Itoa(n)
	nList := make([]int, len(nStr))
	odd := make([]int, 0)
	even := make([]int, 0)

	for i := 0; i < len(nStr); i++ {
		nList[i], _ = strconv.Atoi(string(nStr[i]))
		if nList[i]%2 != 0 {
			odd = append(odd, nList[i])
		} else {
			even = append(even, nList[i])
		}
	}

	if len(odd) == 0 {
		half := len(nList) / 2
		return prod(even[:half])
	} else if len(even) == 0 {
		half := len(nList) / 2
		return sum(odd[:half])
	} else {
		return sum(even) + prod(odd)
	}
}

func sum(lst []int) int {
	sum := 0
	for _, v := range lst {
		sum += v
	}
	return sum
}

func prod(lst []int) int {
	prod := 1
	for _, v := range lst {
		prod *= v
	}
	return prod
}
```

Please note that the Go language doesn't support list slicing, so `even[:half]` and `odd[:half]` will not directly work in Go. I included these as is assuming that you've already implemented the necessary logic or you have your own defined function handling this."}]

