// Returns the largest prime factor of a positive or negative n. Assume abs(n) > 1 and is not prime.
// Optimizes the procedure by only scrutinizing odd factors succeeding 2.
func largestPrimeFactor(n int) float64 {
    n = int(math.Abs(float64(n))) // assign absolute value of n
	lastFactor := 1
	// get rid of 2's
	for n%2 == 0 {
		lastFactor = 2
		n = n / 2
	}
	factor := 3
	maxFactor := math.Sqrt(float64(n)) // assign the square root of n
	for float64(n) > 1 && float64(factor) <= maxFactor {
		if n%factor == 0 {
			n = n / factor
			lastFactor = factor
			for n%factor == 0 {
				n = n / factor
			}
			maxFactor = math.Sqrt(float64(n)) // update the square root of n
		}
		factor += 2
	}
	if n == 1 {
		return float64(lastFactor)
	} else {
		return float64(n)
	}
}

func main() {
	fmt.Println(largestPrimeFactor(10)) // outputs 5
}
