[{"role": "assistant", "content": "Here's the solution implemented in Go:

```go
package main

import "fmt"

func calculate(numbers []int, operation string) (int, int) {
    evenResult, oddResult := 0, 0
    switch operation {
    case "squares":
        for _, num := range numbers {
            if num%2 == 0 {
                evenResult += num * num
            } else {
                oddResult += num * num
            }
        }
        return evenResult, oddResult
    case "cubes":
        evenResult, oddResult = 1, 1
        for _, num := range numbers {
            if num%2 == 0 {
                evenResult *= num * num * num
            } else {
                oddResult *= num * num * num
            }
        }
        if len(numbers) == 0 {
            return 1, 1
        }
        return evenResult, oddResult
    default:
        return 0, 0
    }
}

func main() {
    fmt.Println(calculate([]int{1, 2, 3, 4}, "squares")) // Outputs: 20, 10
    fmt.Println(calculate([]int{1, 2, 3, 4}, "cubes"))   // Outputs: 8, 27
    fmt.Println(calculate([]int{}, "squares"))           // Outputs: 0, 0
    fmt.Println(calculate([]int{}, "cubes"))             // Outputs: 1, 1
}
```

