func divisors(num int) []int {
    divs := []int{1}
    for i := 2; i <= num / 2; i++ {
        if num % i == 0 {
            divs = append(divs, i)
        }
    }
    divs = append(divs, num)
    return divs
}

func divisor_counts(n int, m int) []int {
    counts := make([]int, 0)
    for i := n; i <= m; i++ {
        counts = append(counts, len(divisors(i)))
    }
    return counts
}

func weighted_average(div_counts []int, n int, m int) float64 {
    total_sum := 0.0
    for i, count := range div_counts {
        total_sum += float64(count) * float64(i + n)
    }
    total_count := 0
    for _, count := range div_counts {
        total_count += count
    }
    return math.Round(total_sum / float64(total_count))
}

func custom_base_repr(num int, base int) string {
    if base < 2 || base > 10 {
        return "-1"
    }
    digits := make([]string, 0)
    for num > 0 {
        digits = append([]string{strconv.Itoa(num % base)}, digits...)
        num /= base
    }
    var prefix string
    if base == 2 {
        prefix = "0b"
    } else if base == 8 {
        prefix = "0o"
    } else {
        prefix = ""
    }
    return prefix + strings.Join(digits, "")
}

func rounded_avg_custom_base(n int, m int, base int) string {
    if n > m || base < 2 || base > 10 {
        return "-1"
    }
    div_counts := divisor_counts(n, m)
    weighted_avg := int(weighted_average(div_counts, n, m))
    return custom_base_repr(weighted_avg, base)
}

