```go
package main

import (
    "fmt"
)

// Function to generate primes
func generatePrimes(n int) []int {
    primes := make([]bool, n+1)
    for i := 2; i <= n; i++ {
        primes[i] = true
    }

    p := 2
    for p*p <= n {
        if primes[p] {
            for i := p * p; i <= n; i += p {
                primes[i] = false
            }
        }
        p += 1
    }

    primeNums := make([]int, 0)
    for p := 2; p <= n; p++ {
        if primes[p] {
            primeNums = append(primeNums, p)
        }
    }

    return primeNums
}

// Function to find the first n prime numbers > 2
func firstNPrimes(n int) []int {
    length, increment := 100, 100
    for {
        primes := generatePrimes(length)
        if len(primes) >= n {
            return primes[:n]
        }
        length += increment
    }
}

func main() {
    fmt.Println(firstNPrimes(100))
}
```

This program first choses an arbitrary length for the list of prime numbers. If this length is not enough, it increases the length and tries again, until it has found the required amount of prime numbers. The generatePrimes function implements the Sieve of Eratosthenes algorithm, which generates all prime numbers up to a given limit. It creates a list of prime numbers by iteratively marking the multiples of each prime number starting from 2."}]

