// Function to check if a slice of integers is strictly increasing
func strictlyIncreasing(numbers []int) (bool, error) {
	// Check if slice is empty or contains a single element
	if len(numbers) < 2 {
		return true, nil
	}
	// Check if all elements in slice are strictly increasing
	for i := 0; i < len(numbers)-1; i++ {
		if numbers[i] >= numbers[i+1] {
			return false, errors.New("slice contains non-strictly increasing numbers")
		}
	}
	return true, nil
}

// Function to intersperse a delimiter among strictly 
// increasing integers in a slice
func intersperse(numbers []int, delimiter int) ([]int, error) {
	isStrictlyIncreasing, err := strictlyIncreasing(numbers)
	// Raise an error if the numbers are not strictly increasing
	if err != nil {
		return nil, err
	}
	// Continue if the numbers are strictly increasing
	if isStrictlyIncreasing {
		result := make([]int, 0, len(numbers)*2-1)
		for _, num := range numbers {
			result = append(result, num, delimiter)
		}
		// Remove the last delimiter
		return result[:len(result)-1], nil
	}
	return nil, nil
}

func main() {
	// Test cases
	fmt.Println(intersperse([]int{1, 2, 3}, 4)) // should print [1 4 2 4 3] <nil>
	fmt.Println(intersperse([]int{}, 4)) // should print [] <nil>
}
