import (
	"strconv"
	"math"
)

func Specialfilter(nums []int, limit int) (int, int) {
	var sum int
	var highest int
	for _, num := range nums {
		if num > 10 && strconv.Itoa(num)[0] % 2 == 1 && strconv.Itoa(num)[len(strconv.Itoa(num))-1] % 2 == 1 && isPrime(num) {
			sum += num
			if num > highest {
				highest = num
			}
			if sum > limit {
				return -2, highest
			}
		}
	}
	if sum == 0 {
		return -1, -1
	}
	return sum, highest
}

func isPrime(n int) bool {
	if n <= 1 {
		return false
	}
	if n == 2 {
		return true
	}
	if n % 2 == 0 {
		return false
	}
	sqrtN := int(math.Sqrt(float64(n)))
	for i := 3; i <= sqrtN; i += 2 {
		if n % i == 0 {
			return false
		}
	}
	return true
}
