				minPrevious = min(minPrevious, dp[i-1][j-1])
			}
			if subset[j] <= arr[i] {
				dp[i][j] = dp[i-1][j] + 1
			} else {
				dp[i][j] = minPrevious
			}
		}
	}

	result := dp[len(arr)-1]
	sort.Ints(result)

	for _, modification := range result {
		if modification <= limit {
			return modification
		}
	}

	return -1
}

