// Function to check if list can be sorted by reversing a sublist once and removing one element.
// This function takes a slice as a parameter. Slices are a more flexible, powerful interface for sequences of data.
func checkSort(arr []int) bool {

	// We loop through the length of the array
	for i := range arr {

		// We create a slice (lNew) that is a copy of the original with one element removed.
		lNew := append(arr[:i], arr[i+1:]...) 

		// We need to make a sorted copy of the new slice to compare to.
		sortArr := make([]int, len(lNew))
		copy(sortArr, lNew)
		sort.Ints(sortArr)

		// We also create a reversed copy of the sorted slice.
		revSortArr := make([]int, len(sortArr))
		copy(revSortArr, sortArr)
		for i, j := 0, len(revSortArr)-1; i < j; i, j = i+1, j-1 {
			revSortArr[i], revSortArr[j] = revSortArr[j], revSortArr[i]
		}

		// Check if the list is sorted after reversing.
		if equal(lNew, sortArr) || equal(lNew, revSortArr) {
			return true
		}
	}
	return false
}

// Function to compare if two slices are equal
func equal(a, b []int) bool {
	if len(a) != len(b) {
		return false
	}
	for i, v := range a {
		if v != b[i] {
			return false
		}
	}
	return true
}

// We check for each list in the data.
func customSort(data [][]int) bool {
	for _, arr := range data {
		if !checkSort(arr) {
			return false
		}
	}
	return true
}

func main() {
    fmt.Println(customSort([][]int{{3,2,1},{1,2,3}})) // Prints: true
    fmt.Println(customSort([][]int{{3,5,4},{2,1,4}})) // Prints: true
    fmt.Println(customSort([][]int{{1,2,3,5},{4,3,5,1}})) // Prints: false
    fmt.Println(customSort([][]int{{5,4,3,2,1},{2,4,1,3}})) // Prints: true
}
```

