func Intersperse(numbers []int, delimiter int) []int {
	l := len(numbers)
	if l <= 2 {
		return numbers
	}

	delimitersCount := int(math.Round(math.Sqrt(float64(l))))
	t := time.Now()
	rand.Seed(int64(t.Nanosecond()))

	injected := make([]int, 0, delimitersCount+l)
	injected = append(injected, numbers[0])

	for i := 1; i < len(numbers); i++ {
		if delimitersCount > 0 && rand.Intn(len(numbers)-i+delimitersCount) < delimitersCount {
			injected = append(injected, delimiter)
			delimitersCount--
		}
		injected = append(injected, numbers[i])
	}
	return injected
}
