```go
package main

import (
	"fmt"
	"strconv"
)

func isPrime(n int) bool {
	if n <= 1 {
		return false
	}
	if n <= 3 {
		return true
	}
	if n%2 == 0 || n%3 == 0 {
		return false
	}
	i := 5
	for i*i <= n {
		if n%i == 0 || n%(i+2) == 0 {
			return false
		}
		i += 6
	}
	return true
}

func isSpecial(num int) bool {
	s := strconv.Itoa(num)
	firstDigit := s[0]
	lastDigit := s[len(s)-1]
	if num > 10 && isPrime(num) && 
	(firstDigit == '1' || firstDigit == '3' || firstDigit == '5' || firstDigit == '7' || firstDigit == '9') && 
	(lastDigit == '1' ||  lastDigit == '3' || lastDigit == '5' || lastDigit == '7' || lastDigit == '9') {
		return true
	}
	return false
}

func Specialfilter(nums []int) (int, int) {
	primeSum := 0
	maxPrime := -1
	for _, num := range nums {
		if isSpecial(num) {
			primeSum += num
			if (maxPrime == -1) || (num > maxPrime) {
				maxPrime = num
			}
		}
	}
	if (primeSum == 0) && (maxPrime == -1) {
		return -1, -1
	} else {
		return primeSum, maxPrime
	}
}

func main() {
