	sum := 0
	for _, p := range path {
		sum += grid[p[0]][p[1]]
	}
	return sum
}

// Depth-first search function to find all paths
func dfs(i int, j int, M int, moves [][]int, grid [][]int, path [][]int, maxPath *[][]int, maxSum *int, l int) {
