// We use the sync.Mutex to handle the locking and unlocking of array elements
var mutex = &sync.Mutex{}

// swap function will swap elements i and j in arr
func swap(arr []int, i int, j int) {
	mutex.Lock()
	temp := arr[i]
	arr[i] = arr[j]
	arr[j] = temp
	mutex.Unlock()
}

// sortThird function will sort array by each third element
func sortThird(l []int) []int {
	// Create a copy of the input array
	arr := make([]int, len(l))
	copy(arr, l)

	indices := []int{}
	// Create array of indices for each third element
	for i := 0; i < len(arr); i += 3 {
		indices = append(indices, i)
	}
	// Sort the array of indices based on the value of the respective third element
	sort.Slice(indices, func(i, j int) bool {
		return arr[indices[i]] < arr[indices[j]]
	})
	// Swap the positions of each third element based on the sorted indices
	for i := 0; i < len(arr); i += 3 {
		swap(arr, i, indices[i/3])
	}

	return arr
}

func main() {
	fmt.Println(sortThird([]int{1, 2, 3}))
	fmt.Println(sortThird([]int{5, 6, 3, 4, 8, 9, 2}))
}
