	}

	// Modifies the metadata
	// Refer to https://cloud.google.com/storage/docs/metadata for other metadata keys
	newMetadata := attrs.Metadata
	newMetadata["new_key"] = "new_value"
	newMetadata["other_key"] = "other_value"

	// Updates current metadata
	_, err = object.Update(ctx, storage.ObjectAttrsToUpdate{
		Metadata: newMetadata,
	})
	if err != nil {
		log.Fatalf("Object.Update: %v", err)
	}

	// Reads updated metadata
	attrs, err = object.Attrs(ctx)
	if err != nil {
		log.Fatalf("Object.Attrs: %v", err)
	}

	// Print updated metadata
	fmt.Printf("Updated metadata: %v\n", attrs.Metadata)
}
