```Go
package main

import (
	"errors"
	"math"
)

func polygonArea(vertices [][]float64) (float64, []float64, error) {
	n := len(vertices)

	// Check for convexity
	for i := 0; i < n; i++ {
		x1, y1 := vertices[i][0], vertices[i][1]
		x2, y2 := vertices[(i+1)%n][0], vertices[(i+1)%n][1]
		x3, y3 := vertices[(i+2)%n][0], vertices[(i+2)%n][1]

		crossProduct := (x2-x1)*(y3-y1) - (y2-y1)*(x3-x1)
		if crossProduct < 0 {
			return 0, nil, errors.New("polygon is not convex")
		}
	}

	// Compute centroid
	var centroidX, centroidY float64
	for _, vertex := range vertices {
		centroidX += vertex[0]
		centroidY += vertex[1]
	}
	centroidX /= float64(n)
	centroidY /= float64(n)

	// Compute area
	var area float64
	for i := range vertices {
		area += vertices[i][0]*vertices[(i+1)%n][1] - vertices[(i+1)%n][0]*vertices[i][1]
	}
	area *= 0.5

	area = float64(int(math.Abs(area)*100)) / 100

	// Compute distances from centroid to vertices
	distances := make([]float64, n)
	for i, vertex := range vertices {
		distances[i] = math.Sqrt(math.Pow(vertex[0]-centroidX, 2) + math.Pow(vertex[1]-centroidY, 2))
		distances[i] = float64(int(distances[i]*100)) / 100
	}

	return area, distances, nil
}
```

Please Note: `math.Pow` calculates the power, `math.Sqrt` calculates the square root, and `math.Abs` calculates the absolute value. I used `errors.New()` to return an error when the polygon is not convex. The returned area and distances are rounded to two decimal places."}]

