func CheckIfLastCharIsALetter(txt string) (bool, string) {
    if len(txt) == 0 || txt[len(txt)-1] == ' ' {
        return false, ""
    }

    txt = strings.TrimSpace(txt)
    lastRune := txt[len(txt)-1]

    if !strings.ContainsRune("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ", lastRune) {
        return false, ""
    }

    if strings.ContainsRune("aeiouAEIOU", lastRune) {
        return true, "It's a vowel."
    } 

    return true, ""
}
