func ReverseWords(words []string) []string {
    reversedWords := make([]string, len(words))
    for i, word := range words {
        reverseWord := ""
        for _, c := range word {
            reverseWord = string(c) + reverseWord
        }
        reversedWords[i] = reverseWord
    }
    return reversedWords
}

