func isPrime(n int) bool {
	if n <= 1 {
		return false
	}
	if n == 2 {
		return true
	}
	if n%2 == 0 {
		return false
	}

	sqrtN := int(math.Sqrt(float64(n)))
	for i := 3; i <= sqrtN; i += 2 {
		if n%i == 0 {
			return false
		}
	}

	return true
}

func main() {
	num := 37
	if isPrime(num) {
		fmt.Printf("%d is a prime number\n", num)
	} else {
		fmt.Printf("%d is not a prime number\n", num)
	}
}
```

In this example, the `isPrime` function takes an integer `n` as a parameter and returns a boolean value indicating whether `n` is a prime number or not. 

To check if `n` is a prime number, the function uses a basic primality test algorithm. It first checks if `n` is less than or equal to 1, in which case it returns `false` since prime numbers are greater than 1. If `n` is equal to 2, it returns `true` since 2 is the only even prime number. If `n` is divisible by 2, it returns `false` since even numbers (except for 2) are not prime.

